const setDeviceStatus = `-- name: SetDeviceStatus :execrows
UPDATE devices
SET status = $1
WHERE id = $2 AND deleted_at IS NULL AND status <> $1
`

type SetDeviceStatusParams struct {
	Status string
	ID     pgtype.UUID
}

func (q *Queries) SetDeviceStatus(ctx context.Context, arg SetDeviceStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, setDeviceStatus, arg.Status, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const touchDevicesLastSeen = `-- name: TouchDevicesLastSeen :execrows
UPDATE devices AS d
SET last_seen_at = v.seen_at,
    -- 'pending' as well as 'offline'. A freshly enrolled device starts
    -- 'pending' — it has never been heard from — and hearing from it is exactly
    -- what this statement records. Transitioning only from 'offline' left every
    -- working device in the fleet showing 'pending' forever, because nothing
    -- else ever moved it.
    --
    -- 'degraded' is deliberately left alone: liveness and health are different
    -- questions, and a heartbeat answers only the first.
    status = CASE WHEN d.status IN ('offline', 'pending') THEN 'online'
                  ELSE d.status END
FROM (
    SELECT unnest($1::uuid[])        AS id,
           unnest($2::timestamptz[])   AS seen_at
) AS v
WHERE d.id = v.id
  AND d.deleted_at IS NULL
  -- Never move last_seen_at backwards: a late-arriving flush from a replica
  -- that was slow must not make a live device look stale.
  AND (d.last_seen_at IS NULL OR d.last_seen_at < v.seen_at)
`

type TouchDevicesLastSeenParams struct {
	DeviceIds []pgtype.UUID
	SeenAts   []pgtype.Timestamptz
}

// Batched liveness update.
//
// unnest() turns the batch into a single statement: one round trip and one
// index scan for the whole flush, instead of N statements. At 10,000 devices
// heartbeating every 15 seconds, the difference is the difference between a
// working system and a saturated write path.
func (q *Queries) TouchDevicesLastSeen(ctx context.Context, arg TouchDevicesLastSeenParams) (int64, error) {
	result, err := q.db.Exec(ctx, touchDevicesLastSeen, arg.DeviceIds, arg.SeenAts)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateDevice = `-- name: UpdateDevice :one
UPDATE devices
SET client_name          = COALESCE($1::text, client_name),
    site                 = COALESCE($2::text, site),
    notes                = COALESCE($3::text, notes),
    labels               = COALESCE($4::jsonb, labels),
    allow_custom_scripts = COALESCE($5::boolean, allow_custom_scripts)
WHERE id = $6 AND deleted_at IS NULL
RETURNING id, org_id, hostname, serial_number, hardware_uuid, model_identifier, model_name, chip, arch, cpu_cores, cpu_performance_cores, cpu_efficiency_cores, memory_bytes, disk_total_bytes, os_name, os_version, os_build, agent_version, local_ip, public_ip, primary_mac, site, notes, labels, status, enrollment_state, allow_custom_scripts, last_cpu_percent, last_memory_percent, last_disk_percent, first_enrolled_at, last_seen_at, last_boot_at, connected_replica, enrolled_by_token, created_at, updated_at, deleted_at, client_name, screen_sharing_enabled, vnc_password_sealed
`

type UpdateDeviceParams struct {
	ClientName         *string
	Site               *string
	Notes              *string
	Labels             []byte
	AllowCustomScripts *bool
	ID                 pgtype.UUID
}

// Absent parameters leave their column alone; empty strings clear it. COALESCE
// over a NULL argument is what makes a PATCH partial, and it is why the domain
// input uses pointers — a plain "" could not mean "don't touch this".
func (q *Queries) UpdateDevice(ctx context.Context, arg UpdateDeviceParams) (Device, error) {
	row := q.db.QueryRow(ctx, updateDevice,
		arg.ClientName,
		arg.Site,
		arg.Notes,
		arg.Labels,
		arg.AllowCustomScripts,
		arg.ID,
	)
	var i Device
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.Hostname,
		&i.SerialNumber,
		&i.HardwareUuid,
		&i.ModelIdentifier,
		&i.ModelName,
		&i.Chip,
		&i.Arch,
		&i.CpuCores,
		&i.CpuPerformanceCores,
		&i.CpuEfficiencyCores,
		&i.MemoryBytes,
		&i.DiskTotalBytes,
		&i.OsName,
		&i.OsVersion,
		&i.OsBuild,
		&i.AgentVersion,
		&i.LocalIp,
		&i.PublicIp,
		&i.PrimaryMac,
		&i.Site,
		&i.Notes,
		&i.Labels,
		&i.Status,
		&i.EnrollmentState,
		&i.AllowCustomScripts,
		&i.LastCpuPercent,
		&i.LastMemoryPercent,
		&i.LastDiskPercent,
		&i.FirstEnrolledAt,
		&i.LastSeenAt,
		&i.LastBootAt,
		&i.ConnectedReplica,
		&i.EnrolledByToken,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.ClientName,
		&i.ScreenSharingEnabled,
		&i.VncPasswordSealed,
	)
	return i, err
}
